import type { Operation } from "@buf/googleapis_googleapis.bufbuild_es/google/longrunning/operations_pb.js";
import { RetryInfoSchema } from "@buf/googleapis_googleapis.bufbuild_es/google/rpc/error_details_pb.js";
import type { Status } from "@buf/googleapis_googleapis.bufbuild_es/google/rpc/status_pb.js";
import type { DescMethod } from "@bufbuild/protobuf";
import { MethodOptions_IdempotencyLevel } from "@bufbuild/protobuf/wkt";
import { Code, ConnectError } from "@connectrpc/connect";

const ALPHA_VERSION_PATTERN = /(?:^|\.)v\d+alpha\d+(?:\.|$)/;
const BETA_VERSION_PATTERN = /(?:^|\.)v\d+beta\d+(?:\.|$)/;

export interface ProtoOperationRunner {
  cancel?: (name: string) => Promise<void>;
  onProgress?: (operation: Operation) => void;
  poll: (name: string, signal: AbortSignal) => Promise<Operation>;
  pollIntervalMs?: number;
  signal?: AbortSignal;
  sleep?: (delayMs: number, signal: AbortSignal) => Promise<void>;
  start: (signal: AbortSignal) => Promise<Operation>;
}

export class ProtoOperationError extends Error {
  readonly status: Status;

  constructor(status: Status) {
    super(status.message || `Operation failed with status ${status.code}.`);
    this.name = "ProtoOperationError";
    this.status = status;
  }
}

function abortError(): DOMException {
  return new DOMException("The operation was aborted.", "AbortError");
}

function defaultSleep(delayMs: number, signal: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal.aborted) {
      reject(abortError());
      return;
    }
    function handleAbort() {
      clearTimeout(timeout);
      reject(abortError());
    }
    const timeout = setTimeout(() => {
      signal.removeEventListener("abort", handleAbort);
      resolve();
    }, delayMs);
    signal.addEventListener("abort", handleAbort, { once: true });
  });
}

function requireActive(signal: AbortSignal): void {
  if (signal.aborted) {
    throw abortError();
  }
}

function finishOperation(operation: Operation): Operation {
  if (operation.result.case === "error") {
    throw new ProtoOperationError(operation.result.value);
  }
  if (operation.result.case !== "response") {
    throw new Error("A completed operation must contain a response or error.");
  }
  return operation;
}

async function pollUntilDone(
  operation: Operation,
  poll: ProtoOperationRunner["poll"],
  sleep: NonNullable<ProtoOperationRunner["sleep"]>,
  pollIntervalMs: number,
  signal: AbortSignal,
  onProgress?: ProtoOperationRunner["onProgress"]
): Promise<Operation> {
  let current = operation;
  while (!current.done) {
    if (!current.name) {
      throw new Error("An incomplete operation must have a name for polling.");
    }
    // biome-ignore lint/performance/noAwaitInLoops: each LRO poll must follow the previous response.
    await sleep(pollIntervalMs, signal);
    requireActive(signal);
    current = await poll(current.name, signal);
    onProgress?.(current);
  }
  return current;
}

export async function runProtoOperation({
  cancel,
  onProgress,
  poll,
  pollIntervalMs = 1000,
  signal = new AbortController().signal,
  sleep = defaultSleep,
  start,
}: ProtoOperationRunner): Promise<Operation> {
  let operationName: string | undefined;
  try {
    requireActive(signal);
    const operation = await start(signal);
    operationName = operation.name || undefined;
    onProgress?.(operation);
    const completed = await pollUntilDone(
      operation,
      poll,
      sleep,
      pollIntervalMs,
      signal,
      onProgress
    );
    return finishOperation(completed);
  } catch (error) {
    if (signal.aborted && operationName && cancel) {
      await cancel(operationName);
    }
    throw error;
  }
}

export type ProtoRetryReason =
  | "non-retryable-code"
  | "streaming"
  | "transient"
  | "unsafe";

export interface ProtoRetryDecision {
  delayMs?: number;
  reason: ProtoRetryReason;
  retry: boolean;
}

function getRetryDelayMs(error: ConnectError): number | undefined {
  const delay = error.findDetails(RetryInfoSchema)[0]?.retryDelay;
  if (!delay) {
    return undefined;
  }
  return Math.max(0, Number(delay.seconds) * 1000 + delay.nanos / 1e6);
}

export function getProtoRetryDecision(
  method: DescMethod,
  reason: unknown
): ProtoRetryDecision {
  if (method.methodKind !== "unary") {
    return { reason: "streaming", retry: false };
  }
  if (
    method.idempotency !== MethodOptions_IdempotencyLevel.NO_SIDE_EFFECTS &&
    method.idempotency !== MethodOptions_IdempotencyLevel.IDEMPOTENT
  ) {
    return { reason: "unsafe", retry: false };
  }
  const error = ConnectError.from(reason);
  if (error.code !== Code.Unavailable) {
    return { reason: "non-retryable-code", retry: false };
  }
  const delayMs = getRetryDelayMs(error);
  return delayMs === undefined
    ? { reason: "transient", retry: true }
    : { delayMs, reason: "transient", retry: true };
}

export interface ProtoPartialResultRecovery {
  label: string;
  resourceName: string;
}

export interface ProtoPartialResult {
  complete: boolean;
  recovery: readonly ProtoPartialResultRecovery[];
  unreachable: readonly string[];
  warning?: string;
}

function resourceLabel(resourceName: string): string {
  const segments = resourceName.split("/");
  return segments.at(-1) || resourceName;
}

export function getProtoPartialResult(response: {
  unreachable?: unknown;
}): ProtoPartialResult {
  const unreachable = Array.isArray(response.unreachable)
    ? response.unreachable.filter(
        (value): value is string => typeof value === "string" && value !== ""
      )
    : [];
  if (unreachable.length === 0) {
    return { complete: true, recovery: [], unreachable: [] };
  }
  const noun = unreachable.length === 1 ? "resource" : "resources";
  return {
    complete: false,
    recovery: unreachable.map((resourceName) => ({
      label: `Retry ${resourceLabel(resourceName)}`,
      resourceName,
    })),
    unreachable,
    warning: `Some results are unavailable from ${unreachable.length} ${noun}.`,
  };
}

export interface ProtoPurgePlan {
  confirmationRequired: boolean;
  count: number;
  mode: "execute" | "preview";
  sample: readonly string[];
  warning: string;
}

export function getProtoPurgePlan(
  request: { filter: string; force: boolean },
  response: { purgeCount: number; purgeSample: readonly string[] }
): ProtoPurgePlan {
  if (!request.filter) {
    throw new Error("A purge plan requires a filter.");
  }
  return {
    confirmationRequired: request.force,
    count: response.purgeCount,
    mode: request.force ? "execute" : "preview",
    sample: response.purgeSample,
    warning: request.force
      ? "This permanently deletes every resource matching the filter."
      : "Preview only. No resources will be deleted.",
  };
}

export type ProtoPolicyPreviewAction =
  | "commit"
  | "start-preview"
  | "stop-preview";

export interface ProtoPolicyPreviewPlan {
  action: ProtoPolicyPreviewAction;
  confirmationRequired: boolean;
  enforcesPolicy: boolean;
  notice: string;
}

export function getProtoPolicyPreviewPlan(
  action: ProtoPolicyPreviewAction
): ProtoPolicyPreviewPlan {
  switch (action) {
    case "start-preview":
      return {
        action,
        confirmationRequired: false,
        enforcesPolicy: false,
        notice:
          "Preview compares the experiment with live traffic without enforcing it.",
      };
    case "stop-preview":
      return {
        action,
        confirmationRequired: false,
        enforcesPolicy: false,
        notice: "Stopping preview does not change the live policy.",
      };
    case "commit":
      return {
        action,
        confirmationRequired: true,
        enforcesPolicy: true,
        notice: "Commit replaces the live policy and deletes the experiment.",
      };
    default:
      throw new Error(
        `Unsupported policy preview action: ${action satisfies never}`
      );
  }
}

export type ProtoStabilityLevel = "alpha" | "beta" | "deprecated" | "stable";

export interface ProtoStability {
  guidance?: string;
  level: ProtoStabilityLevel;
  preview: boolean;
}

export interface ProtoStabilityDescriptor {
  deprecated: boolean;
  typeName: string;
}

export function getProtoStability({
  deprecated,
  typeName,
}: ProtoStabilityDescriptor): ProtoStability {
  if (deprecated) {
    return {
      guidance:
        "Deprecated: migrate before the documented support period ends.",
      level: "deprecated",
      preview: false,
    };
  }
  if (ALPHA_VERSION_PATTERN.test(typeName)) {
    return {
      guidance: "Alpha preview: breaking changes are expected.",
      level: "alpha",
      preview: true,
    };
  }
  if (BETA_VERSION_PATTERN.test(typeName)) {
    return {
      guidance: "Beta preview: changes remain possible before stability.",
      level: "beta",
      preview: true,
    };
  }
  return { level: "stable", preview: false };
}

import {
  FieldBehavior,
  field_behavior,
} from "@buf/googleapis_googleapis.bufbuild_es/google/api/field_behavior_pb.js";
import {
  resource,
  resource_reference,
} from "@buf/googleapis_googleapis.bufbuild_es/google/api/resource_pb.js";
import {
  create,
  type DescField,
  type DescMessage,
  getExtension,
} from "@bufbuild/protobuf";
import {
  FieldOptionsSchema,
  MessageOptionsSchema,
} from "@bufbuild/protobuf/wkt";

export interface ProtoResourceMetadata {
  nameField: string;
  patterns: string[];
  plural: string;
  singular: string;
  type: string;
}

export interface ProtoResourceReference {
  childType?: string;
  type?: string;
}

export function getProtoResourceMetadata(
  desc: DescMessage
): ProtoResourceMetadata | undefined {
  const metadata = getExtension(
    desc.proto.options ?? create(MessageOptionsSchema),
    resource
  );
  if (!metadata.type && metadata.pattern.length === 0) {
    return;
  }
  return {
    nameField: metadata.nameField || "name",
    patterns: [...metadata.pattern],
    plural: metadata.plural,
    singular: metadata.singular,
    type: metadata.type,
  };
}

export function getProtoResourceReference(
  field: DescField
): ProtoResourceReference | undefined {
  const reference = getExtension(
    field.proto.options ?? create(FieldOptionsSchema),
    resource_reference
  );
  if (!(reference.type || reference.childType)) {
    return;
  }
  return {
    childType: reference.childType || undefined,
    type: reference.type || undefined,
  };
}

export function getProtoFieldBehaviors(
  field: DescField
): readonly FieldBehavior[] {
  return getExtension(
    field.proto.options ?? create(FieldOptionsSchema),
    field_behavior
  ).filter((behavior) => behavior !== FieldBehavior.FIELD_BEHAVIOR_UNSPECIFIED);
}

export function isSingletonProtoResource(desc: DescMessage): boolean {
  const metadata = getProtoResourceMetadata(desc);
  if (!metadata || metadata.patterns.length === 0) {
    return false;
  }
  return metadata.patterns.every((pattern) => {
    const lastSegment = pattern.split("/").at(-1);
    return Boolean(lastSegment && !lastSegment.includes("{"));
  });
}

import type { DescMessage } from "@bufbuild/protobuf";

export interface ProtoAnnotations {
  fields?: Record<string, string>;
  messages?: Record<string, string>;
  oneofs?: Record<string, string>;
}

const protoAnnotationsRegistry = new WeakMap<DescMessage, ProtoAnnotations>();

export function registerProtoAnnotations(
  desc: DescMessage,
  annotations: ProtoAnnotations
): ProtoAnnotations {
  protoAnnotationsRegistry.set(desc, annotations);
  return annotations;
}

export function getRegisteredProtoAnnotations(
  desc: DescMessage
): ProtoAnnotations | undefined {
  return protoAnnotationsRegistry.get(desc);
}

import {
  FieldBehavior,
  field_behavior as fieldBehaviorExtension,
} from "@buf/googleapis_googleapis.bufbuild_es/google/api/field_behavior_pb.js";
import {
  create,
  type DescField,
  type DescMessage,
  type DescOneof,
  getExtension,
} from "@bufbuild/protobuf";
import {
  type FieldMask,
  FieldMaskSchema,
  FieldOptionsSchema,
} from "@bufbuild/protobuf/wkt";

type FormRecord = Record<string, unknown>;

const NON_UPDATABLE_BEHAVIORS = new Set([
  FieldBehavior.IDENTIFIER,
  FieldBehavior.IMMUTABLE,
  FieldBehavior.OUTPUT_ONLY,
]);

function isRecord(value: unknown): value is FormRecord {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function hasDirtyValue(value: unknown): boolean {
  if (value === true) {
    return true;
  }
  if (Array.isArray(value)) {
    return value.some(hasDirtyValue);
  }
  if (isRecord(value)) {
    return Object.values(value).some(hasDirtyValue);
  }
  return false;
}

function fieldPath(prefix: string, field: DescField): string {
  return prefix ? `${prefix}.${field.name}` : field.name;
}

function isUpdatableField(field: DescField): boolean {
  const behaviors = getExtension(
    field.proto.options ?? create(FieldOptionsSchema),
    fieldBehaviorExtension
  );
  return behaviors.every((behavior) => !NON_UPDATABLE_BEHAVIORS.has(behavior));
}

function findField(
  schema: DescMessage,
  segment: string
): DescField | undefined {
  return schema.fields.find(
    (field) =>
      field.localName === segment ||
      field.name === segment ||
      field.jsonName === segment
  );
}

function normalizeFieldPath(schema: DescMessage, path: string): string {
  if (path === "*") {
    return path;
  }

  const segments = path.split(".").filter(Boolean);
  if (segments.length === 0) {
    throw new Error("Field mask paths cannot be empty.");
  }

  const normalized: string[] = [];
  let currentSchema = schema;
  for (const [index, segment] of segments.entries()) {
    const field = findField(currentSchema, segment);
    if (!field) {
      throw new Error(`Unknown field mask path: ${path}`);
    }
    normalized.push(field.name);

    if (index === segments.length - 1) {
      break;
    }
    if (field.fieldKind === "list" || field.fieldKind === "map") {
      break;
    }
    if (field.fieldKind !== "message") {
      throw new Error(`Field mask path cannot traverse scalar field: ${path}`);
    }
    currentSchema = field.message;
  }
  return normalized.join(".");
}

function fieldOrder(schema: DescMessage, path: string): number[] {
  if (path === "*") {
    return [-1];
  }

  const order: number[] = [];
  let currentSchema = schema;
  for (const segment of path.split(".")) {
    const index = currentSchema.fields.findIndex(
      (candidate) => candidate.name === segment
    );
    order.push(index);
    const field = currentSchema.fields[index];
    if (field?.fieldKind !== "message") {
      break;
    }
    currentSchema = field.message;
  }
  return order;
}

function compareFieldOrder(
  schema: DescMessage,
  left: string,
  right: string
): number {
  const leftOrder = fieldOrder(schema, left);
  const rightOrder = fieldOrder(schema, right);
  const length = Math.max(leftOrder.length, rightOrder.length);
  for (let index = 0; index < length; index += 1) {
    const difference = (leftOrder[index] ?? -1) - (rightOrder[index] ?? -1);
    if (difference !== 0) {
      return difference;
    }
  }
  return left.localeCompare(right);
}

/** Build a validated, canonical FieldMask from TypeScript or protobuf paths. */
export function createFieldMask(
  schema: DescMessage,
  paths: readonly string[]
): FieldMask {
  const normalizedPaths = [
    ...new Set(paths.map((path) => normalizeFieldPath(schema, path))),
  ];
  if (normalizedPaths.includes("*")) {
    return create(FieldMaskSchema, { paths: ["*"] });
  }
  const minimizedPaths = normalizedPaths.filter(
    (path) =>
      !normalizedPaths.some(
        (candidate) => candidate !== path && path.startsWith(`${candidate}.`)
      )
  );
  minimizedPaths.sort((left, right) => compareFieldOrder(schema, left, right));
  return create(FieldMaskSchema, { paths: minimizedPaths });
}

function collectFieldPaths(
  field: DescField,
  dirtyValue: unknown,
  currentValue: unknown,
  initialValue: unknown,
  prefix: string
): string[] {
  if (!(hasDirtyValue(dirtyValue) && isUpdatableField(field))) {
    return [];
  }

  const path = fieldPath(prefix, field);
  if (
    dirtyValue === true ||
    field.fieldKind === "list" ||
    field.fieldKind === "map"
  ) {
    return [path];
  }
  if (field.fieldKind !== "message" || !isRecord(dirtyValue)) {
    return [path];
  }

  const nestedPaths = collectMessagePaths(
    field.message,
    dirtyValue,
    isRecord(currentValue) ? currentValue : {},
    isRecord(initialValue) ? initialValue : {},
    path
  );
  return nestedPaths.length > 0 ? nestedPaths : [path];
}

function collectOneofPaths(
  oneof: DescOneof,
  dirtyValue: unknown,
  currentValue: unknown,
  initialValue: unknown,
  prefix: string
): string[] {
  if (!hasDirtyValue(dirtyValue)) {
    return [];
  }

  const selectedOneof =
    isRecord(currentValue) && typeof currentValue.case === "string"
      ? currentValue
      : initialValue;
  if (!isRecord(selectedOneof)) {
    return [];
  }
  const selectedCase = selectedOneof.case;
  if (typeof selectedCase !== "string") {
    return [];
  }
  const selectedField = oneof.fields.find(
    (field) => field.localName === selectedCase
  );
  if (!selectedField) {
    return [];
  }

  const nestedDirtyValue =
    isRecord(dirtyValue) &&
    dirtyValue.case !== true &&
    hasDirtyValue(dirtyValue.value)
      ? dirtyValue.value
      : true;
  const initialOneofValue = isRecord(initialValue)
    ? initialValue.value
    : undefined;
  return collectFieldPaths(
    selectedField,
    nestedDirtyValue,
    selectedOneof.value,
    initialOneofValue,
    prefix
  );
}

function collectMessagePaths(
  schema: DescMessage,
  dirtyFields: FormRecord,
  currentValues: FormRecord,
  initialValues: FormRecord,
  prefix = ""
): string[] {
  return schema.members.flatMap((member) => {
    if (member.kind === "oneof") {
      return collectOneofPaths(
        member,
        dirtyFields[member.localName],
        currentValues[member.localName],
        initialValues[member.localName],
        prefix
      );
    }
    return collectFieldPaths(
      member,
      dirtyFields[member.localName],
      currentValues[member.localName],
      initialValues[member.localName],
      prefix
    );
  });
}

/** Build an update mask from react-hook-form's dirty field tree. */
export function createUpdateMask(
  schema: DescMessage,
  dirtyFields: unknown,
  currentValues: unknown,
  initialValues?: unknown
): FieldMask {
  const paths = collectMessagePaths(
    schema,
    isRecord(dirtyFields) ? dirtyFields : {},
    isRecord(currentValues) ? currentValues : {},
    isRecord(initialValues) ? initialValues : {}
  );
  return createFieldMask(schema, paths);
}

import type { DescMessage, MessageValidType } from "@bufbuild/protobuf";
import type {
  FormValues,
  StandardSchemaV1,
} from "../core/index.js";

import {
  type ProtoFormOptions,
  validateFormValuesAgainstProtoSchema,
} from "./provider.js";
import { createDescriptorAwareStandardSchema } from "./validation-schema.js";

function isFormValueObject(value: unknown): value is FormValues {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Expose protovalidate + CEL validation of a proto message as a Standard
 * Schema over FORM values: input is the form value bag, output is the
 * validated typed message, and failure issues carry form-shaped paths
 * (camelCase keys, oneofs flattened, map keys resolved to entry indices).
 *
 * This is the interop seam: anything that speaks Standard Schema v1
 * (React Hook Form via standardSchemaResolver, TanStack Form natively)
 * gets proto validation without importing protovalidate directly.
 */
export function createProtoFormSchema<
  Input extends object = FormValues,
  Desc extends DescMessage = DescMessage,
>(
  desc: Desc,
  options: ProtoFormOptions = {}
): StandardSchemaV1<Input, MessageValidType<Desc>> {
  const messageSchema = createDescriptorAwareStandardSchema(desc, options);

  return {
    "~standard": {
      validate: (value) => {
        if (!isFormValueObject(value)) {
          return {
            issues: [
              { message: "Expected form values to be an object.", path: [] },
            ],
          };
        }
        return validateFormValuesAgainstProtoSchema(
          desc,
          value,
          messageSchema,
          options
        );
      },
      vendor: "protoform",
      version: 1,
    },
  };
}

import {
  BadRequestSchema,
  DebugInfoSchema,
  ErrorInfoSchema,
  HelpSchema,
  LocalizedMessageSchema,
  PreconditionFailureSchema,
  QuotaFailureSchema,
  RequestInfoSchema,
  ResourceInfoSchema,
  RetryInfoSchema,
} from "@buf/googleapis_googleapis.bufbuild_es/google/rpc/error_details_pb.js";
import { Code, ConnectError } from "@connectrpc/connect";

const CODE_LABELS: Record<number, string> = {
  [Code.Canceled]: "canceled",
  [Code.Unknown]: "unknown",
  [Code.InvalidArgument]: "invalid_argument",
  [Code.DeadlineExceeded]: "deadline_exceeded",
  [Code.NotFound]: "not_found",
  [Code.AlreadyExists]: "already_exists",
  [Code.PermissionDenied]: "permission_denied",
  [Code.ResourceExhausted]: "resource_exhausted",
  [Code.FailedPrecondition]: "failed_precondition",
  [Code.Aborted]: "aborted",
  [Code.OutOfRange]: "out_of_range",
  [Code.Unimplemented]: "unimplemented",
  [Code.Internal]: "internal",
  [Code.Unavailable]: "unavailable",
  [Code.DataLoss]: "data_loss",
  [Code.Unauthenticated]: "unauthenticated",
};

/**
 * Get a human-readable label for a gRPC status code.
 */
export function grpcCodeLabel(code: number): string {
  return CODE_LABELS[code] ?? `code_${code}`;
}

/**
 * Extract a human-readable message from a Connect/gRPC error.
 * Preserves all available information: message, field violations, and gRPC code.
 */
export function formatConnectError(error: unknown): string {
  if (error instanceof ConnectError) {
    const violations = extractFieldViolations(error);
    const rawMessage = error.rawMessage;
    const codeLabel = grpcCodeLabel(error.code);

    const parts: string[] = [];
    if (rawMessage) {
      parts.push(rawMessage);
    }
    if (violations.length > 0) {
      parts.push(
        violations.map((v) => `${v.field}: ${v.description}`).join("; ")
      );
    }
    if (parts.length === 0) {
      return codeLabel;
    }
    return `${parts.join(" — ")} (code: ${codeLabel})`;
  }
  if (error instanceof Error) {
    return error.message;
  }
  return String(error);
}

export interface FieldViolation {
  description: string;
  field: string;
}

/**
 * Extract field violations from Connect error details via the generated
 * `google.rpc.BadRequest` schema. Returns an empty array when no
 * BadRequest detail is attached or parsing fails.
 */
export function extractFieldViolations(error: ConnectError): FieldViolation[] {
  const violations: FieldViolation[] = [];
  try {
    for (const badRequest of error.findDetails(BadRequestSchema)) {
      for (const v of badRequest.fieldViolations) {
        violations.push({ description: v.description, field: v.field });
      }
    }
  } catch {
    // Unexpected parse failure: fall through to empty.
  }
  return violations;
}

/**
 * Format a toast error message for API operations.
 * Pattern: "Failed to {action} {entity}: {formatted error with code}"
 */
export function formatToastErrorMessage({
  action,
  entity,
  error,
}: {
  action: string;
  entity: string;
  error: unknown;
}): string {
  return `Failed to ${action} ${entity}: ${formatConnectError(error)}`;
}

export interface HelpLink {
  description: string;
  url: string;
}

export interface PreconditionViolation {
  description: string;
  subject: string;
  type: string;
}

export interface QuotaViolation {
  description: string;
  subject: string;
}

export interface ConnectErrorContext {
  /** gRPC status code label (e.g. "invalid_argument"). Always populated for ConnectError. */
  code?: string;
  /** Dev-only stack frames / detail from google.rpc.DebugInfo. */
  debug?: { detail?: string; stackEntries?: string[] };
  /** Service domain from `google.rpc.ErrorInfo`. */
  domain?: string;
  /** Links the backend suggests the user follow (docs, status pages). */
  helpLinks: HelpLink[];
  /** Human-friendly top-level message. Prefers `LocalizedMessage.message` over `rawMessage`. */
  message?: string;
  /** Locale of the localized message if one was provided. */
  messageLocale?: string;
  /** Extra ErrorInfo metadata the server attached. */
  metadata?: Record<string, string>;
  /** Precondition failures (typed, not per-field). */
  preconditionViolations: PreconditionViolation[];
  /** Quota failures. */
  quotaViolations: QuotaViolation[];
  /** Domain-scoped machine reason from `google.rpc.ErrorInfo` (useful for logs/telemetry). */
  reason?: string;
  /** Opaque request identifier for support tickets. */
  requestId?: string;
  /** Affected resource, if reported. */
