export type ProtoMethodCategory = "batch" | "custom" | "standard";
export type ProtoMethodExecution = "long-running" | "streaming" | "unary";

export interface ProtoHttpBinding {
  bodyFields: readonly string[];
  method: string;
  path: string;
  pathFields: readonly string[];
  queryFields: readonly string[];
}

export interface ProtoOperationInfo {
  metadataType: string;
  responseType: string;
}

export interface ProtoMethodWorkflow {
  category: ProtoMethodCategory;
  execution: ProtoMethodExecution;
  httpBindings: readonly ProtoHttpBinding[];
  method: DescMethod;
  operation?: ProtoOperationInfo;
}

const STANDARD_METHOD_PATTERN = /^(Create|Delete|Get|List|Update)[A-Z]/;
const PATH_FIELD_PATTERN = /\{([^}=]+)(?:=[^}]*)?\}/g;

function getMethodCategory(name: string): ProtoMethodCategory {
  if (name.startsWith("Batch")) {
    return "batch";
  }
  return STANDARD_METHOD_PATTERN.test(name) ? "standard" : "custom";
}

function getHttpPattern(rule: HttpRule): { method: string; path: string } {
  const { pattern } = rule;
  if (pattern.case === undefined) {
    return { method: "", path: "" };
  }
  if (pattern.case === "custom") {
    return {
      method: pattern.value.kind.toUpperCase(),
      path: pattern.value.path,
    };
  }
  return {
    method: pattern.case.toUpperCase(),
    path: pattern.value,
  };
}

function parseHttpBinding(
  method: DescMethod,
  rule: HttpRule
): ProtoHttpBinding {
  const pattern = getHttpPattern(rule);
  const pathFields = Array.from(
    pattern.path.matchAll(PATH_FIELD_PATTERN),
    (match) => match[1]
  ).filter((field): field is string => field !== undefined);
  const requestFields = method.input.fields.map((field) => field.name);
  let bodyFields: string[] = [];
  let queryFields: string[] = [];
  if (rule.body === "*") {
    bodyFields = requestFields.filter((field) => !pathFields.includes(field));
  } else if (rule.body) {
    bodyFields = [rule.body];
    queryFields = requestFields.filter(
      (field) => !pathFields.includes(field) && field !== rule.body
    );
  } else {
    queryFields = requestFields.filter((field) => !pathFields.includes(field));
  }

  return {
    bodyFields,
    method: pattern.method,
    path: pattern.path,
    pathFields,
    queryFields,
  };
}

export function getProtoMethodWorkflow(
  method: DescMethod
): ProtoMethodWorkflow {
  const options = method.proto.options ?? create(MethodOptionsSchema);
  const httpRule = hasExtension(options, http)
    ? getExtension(options, http)
    : undefined;
  const operationInfo = hasExtension(options, operation_info)
    ? getExtension(options, operation_info)
    : undefined;
  const streaming = method.methodKind !== "unary";
  const longRunning = method.output.typeName === OperationSchema.typeName;
  let execution: ProtoMethodExecution = "unary";
  if (streaming) {
    execution = "streaming";
  } else if (longRunning) {
    execution = "long-running";
  }
  const operation =
    operationInfo?.metadataType && operationInfo.responseType
      ? {
          metadataType: operationInfo.metadataType,
          responseType: operationInfo.responseType,
        }
      : undefined;

  return {
    category: getMethodCategory(method.name),
    execution,
    httpBindings: httpRule
      ? [httpRule, ...httpRule.additionalBindings].map((rule) =>
          parseHttpBinding(method, rule)
        )
      : [],
    method,
    operation,
  };
}

import type { DescField, DescMessage, DescOneof } from "@bufbuild/protobuf";

/**
 * Convert a server-side proto field path into the camelCase form path used by
 * Protoform adapters. Oneof branches flatten under `{oneofLocalName}.value`.
 */
export function protoPathToFormPath(
  schema: DescMessage,
  serverPath: string
): string | null {
  if (!serverPath) {
    return null;
  }
  const path = walk(schema, serverPath.split("."));
  return path ? path.join(".") : null;
}

function walk(
  current: DescMessage,
  segments: readonly string[]
): string[] | null {
  if (segments.length === 0) {
    return [];
  }
  const [head, ...rest] = segments;
  if (!head) {
    return null;
  }
  const resolved = findMember(current, head);
  if (!resolved) {
    return null;
  }

  if (resolved.kind === "oneof") {
    if (rest.length === 0) {
      return [resolved.oneof.localName];
    }
    const [branchName, ...afterBranch] = rest;
    if (!branchName) {
      return null;
    }
    const branch = resolved.oneof.fields.find(
      (candidate) => candidate.name === branchName
    );
    if (!branch) {
      return null;
    }
    const tail = walkInto(branch, afterBranch);
    return tail === null ? null : [resolved.oneof.localName, "value", ...tail];
  }

  const { field } = resolved;
  const formPath = field.oneof
    ? [field.oneof.localName, "value"]
    : [field.localName];
  if (rest.length === 0) {
    return formPath;
  }
  if (!field.message) {
    return null;
  }
  const tail = walk(field.message, rest);
  return tail === null ? null : [...formPath, ...tail];
}

function walkInto(
  field: DescField,
  segments: readonly string[]
): string[] | null {
  if (segments.length === 0) {
    return [];
  }
  return field.message ? walk(field.message, segments) : null;
}

type Resolved =
  | { kind: "field"; field: DescField }
  | { kind: "oneof"; oneof: DescOneof };

function findMember(
  message: DescMessage,
  protoName: string
): Resolved | undefined {
  for (const member of message.members) {
    if (member.kind === "oneof") {
      if (member.name === protoName) {
        return { kind: "oneof", oneof: member };
      }
      const field = member.fields.find(
        (candidate) => candidate.name === protoName
      );
      if (field) {
        return { field, kind: "field" };
      }
    } else if (member.name === protoName) {
      return { field: member, kind: "field" };
    }
  }
  return;
}

